window.BlackoutSpeech = (function () {
  let currentFinish = null;
  function listVoices() {
    try {
      return window.speechSynthesis.getVoices() || [];
    } catch (e) {
      return [];
    }
  }
  function chineseVoice(voices) {
    for (let i = 0; i < voices.length; i += 1) {
      const lang = String(voices[i].lang || "").toLowerCase();
      if (lang.indexOf("zh") === 0) {
        return voices[i];
      }
    }
    return null;
  }
  function waitForVoices() {
    return new Promise(function (resolve) {
      const existing = listVoices();
      if (existing.length > 0 || !("speechSynthesis" in window)) {
        resolve(existing);
        return;
      }
      let done = false;
      function finish() {
        if (done) {
          return;
        }
        done = true;
        try {
          window.speechSynthesis.removeEventListener("voiceschanged", finish);
        } catch (e) {}
        resolve(listVoices());
      }
      try {
        window.speechSynthesis.addEventListener("voiceschanged", finish);
      } catch (e) {}
      window.setTimeout(finish, 1000);
    });
  }
  async function hasChineseVoice() {
    if (!("speechSynthesis" in window)) {
      return false;
    }
    const voices = await waitForVoices();
    return chineseVoice(voices) !== null;
  }
  function prime() {
    try {
      const utter = new SpeechSynthesisUtterance("");
      window.speechSynthesis.speak(utter);
    } catch (e) {}
  }
  function speak(text) {
    const spoken = String(text || "");
    return new Promise(function (resolve) {
      if (!spoken) {
        resolve();
        return;
      }
      let settled = false;
      function finish() {
        if (settled) {
          return;
        }
        settled = true;
        window.clearTimeout(timer);
        if (currentFinish === finish) {
          currentFinish = null;
        }
        resolve();
      }
      const timer = window.setTimeout(finish, Math.max(1500, spoken.length * 350));
      currentFinish = finish;
      try {
        if (!("speechSynthesis" in window)) {
          return;
        }
        const utter = new SpeechSynthesisUtterance(spoken);
        utter.lang = "zh-CN";
        const voice = chineseVoice(listVoices());
        if (voice) {
          utter.voice = voice;
        }
        utter.onend = finish;
        utter.onerror = finish;
        window.speechSynthesis.speak(utter);
      } catch (e) {
        finish();
      }
    });
  }
  function cancel() {
    try {
      if ("speechSynthesis" in window) {
        window.speechSynthesis.cancel();
      }
    } catch (e) {}
    if (currentFinish) {
      const finish = currentFinish;
      currentFinish = null;
      finish();
    }
  }
  function speaking() {
    try {
      return Boolean(window.speechSynthesis && window.speechSynthesis.speaking);
    } catch (e) {
      return false;
    }
  }
  return {
    speak: speak,
    cancel: cancel,
    prime: prime,
    speaking: speaking,
    hasChineseVoice: hasChineseVoice,
    checkChineseVoice: hasChineseVoice
  };
})();
