window.BlackoutResult = (function () {
  let sessionId = "";
  let markdown = "";
  const STORAGE_KEY = "blackout_active_session_id";
  function el(id) {
    return document.getElementById(id);
  }
  function showPage(page) {
    el("page-start").hidden = page !== "start";
    el("page-black").hidden = page !== "black";
    el("page-result").hidden = page !== "result";
  }
  function makeSection(title, items) {
    const box = document.createElement("div");
    box.className = "sec";
    const head = document.createElement("h3");
    head.textContent = title;
    box.appendChild(head);
    const list = document.createElement("ul");
    (items || []).forEach(function (item) {
      const li = document.createElement("li");
      li.textContent = String(item);
      list.appendChild(li);
    });
    box.appendChild(list);
    return box;
  }
  function isWebUrl(value) {
    try {
      const parsed = new URL(String(value));
      return parsed.protocol === "http:" || parsed.protocol === "https:";
    } catch (e) {
      return false;
    }
  }
  function makeTasks(tasks) {
    const box = document.createElement("div");
    box.className = "sec";
    const head = document.createElement("h3");
    head.textContent = "后台查到和写好的";
    box.appendChild(head);
    const list = document.createElement("ul");
    (tasks || []).forEach(function (task) {
      const li = document.createElement("li");
      const main = document.createElement("span");
      main.textContent = String(task.conclusion || task.instruction || "");
      li.appendChild(main);
      if (task.detail) {
        const details = document.createElement("details");
        const summary = document.createElement("summary");
        summary.textContent = "详情";
        details.appendChild(summary);
        const body = document.createElement("p");
        body.textContent = String(task.detail);
        details.appendChild(body);
        (task.sources || []).forEach(function (source) {
          if (!source || !isWebUrl(source.url)) {
            return;
          }
          const link = document.createElement("a");
          link.href = String(source.url);
          link.rel = "noopener noreferrer";
          link.textContent = String(source.title || source.url);
          const line = document.createElement("p");
          line.appendChild(link);
          details.appendChild(line);
        });
        li.appendChild(details);
      }
      list.appendChild(li);
    });
    box.appendChild(list);
    return box;
  }
  function showResult(result, id) {
    if (id) {
      sessionId = String(id);
    }
    const data = result || {};
    markdown = String(data.markdown || "");
    el("resultTitle").textContent = String(data.title || "成果");
    el("degradedNotice").hidden = !data.degraded;
    el("resultErr").textContent = "";
    const box = el("result");
    box.replaceChildren();
    const goalBox = document.createElement("div");
    goalBox.className = "sec";
    const goalHead = document.createElement("h3");
    goalHead.textContent = "本次目标";
    goalBox.appendChild(goalHead);
    const goalText = document.createElement("p");
    goalText.textContent = String(data.goal || "");
    goalBox.appendChild(goalText);
    box.appendChild(goalBox);
    if ((data.decisions || []).length > 0) {
      box.appendChild(makeSection("决定", data.decisions));
    }
    if ((data.todos || []).length > 0) {
      box.appendChild(makeSection("待办", data.todos));
    }
    if ((data.parking_lot || []).length > 0) {
      box.appendChild(makeSection("停车场", data.parking_lot));
    }
    if ((data.open_questions || []).length > 0) {
      box.appendChild(makeSection("还没想清楚", data.open_questions));
    }
    if ((data.contradictions || []).length > 0) {
      box.appendChild(makeSection("前后矛盾", data.contradictions));
    }
    if ((data.unexpanded_points || []).length > 0) {
      box.appendChild(makeSection("没说完的点", data.unexpanded_points));
    }
    if ((data.tasks || []).length > 0) {
      box.appendChild(makeTasks(data.tasks));
    }
    const sketchTexts = (data.sketches || []).map(function (sketch) {
      return String((sketch && sketch.description) || "");
    }).filter(function (text) { return text.length > 0; });
    if (sketchTexts.length > 0) {
      box.appendChild(makeSection("纸上草稿", sketchTexts));
    }
    showPage("result");
  }
  function fallbackCopy(text) {
    return new Promise(function (resolve) {
      const area = document.createElement("textarea");
      area.value = text;
      document.body.appendChild(area);
      area.select();
      try {
        document.execCommand("copy");
      } catch (e) {}
      area.remove();
      resolve();
    });
  }
  async function copyMarkdown() {
    const button = el("copyBtn");
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        await navigator.clipboard.writeText(markdown);
      } else {
        await fallbackCopy(markdown);
      }
    } catch (e) {
      await fallbackCopy(markdown);
    }
    button.textContent = "已复制";
    window.setTimeout(function () {
      button.textContent = "复制为 Markdown";
    }, 1500);
  }
  function scaleImage(file) {
    return new Promise(function (resolve, reject) {
      const url = URL.createObjectURL(file);
      const image = new Image();
      image.onload = function () {
        try {
          const longSide = Math.max(image.naturalWidth, image.naturalHeight) || 1;
          const ratio = Math.min(1, 1600 / longSide);
          const canvas = document.createElement("canvas");
          canvas.width = Math.max(1, Math.round(image.naturalWidth * ratio));
          canvas.height = Math.max(1, Math.round(image.naturalHeight * ratio));
          const ctx = canvas.getContext("2d");
          ctx.drawImage(image, 0, 0, canvas.width, canvas.height);
          URL.revokeObjectURL(url);
          canvas.toBlob(function (blob) {
            if (blob) {
              resolve(blob);
            } else {
              reject(new Error("图片处理失败"));
            }
          }, "image/jpeg", 0.85);
        } catch (e) {
          URL.revokeObjectURL(url);
          reject(e);
        }
      };
      image.onerror = function () {
        URL.revokeObjectURL(url);
        reject(new Error("图片读取失败"));
      };
      image.src = url;
    });
  }
  async function uploadSketch(file) {
    const label = el("sketchLabel");
    const input = el("sketchInput");
    el("resultErr").textContent = "";
    label.textContent = "正在识别…";
    try {
      const blob = await scaleImage(file);
      const form = new FormData();
      form.append("image", blob, "sketch.jpg");
      const response = await fetch("/api/sessions/" + sessionId + "/sketches", {
        method: "POST",
        body: form
      });
      const data = await response.json();
      if (!response.ok) {
        throw new Error((data.error && data.error.message) || "草稿识别失败，请再试一次。");
      }
      showResult(data, sessionId);
    } catch (e) {
      el("resultErr").textContent = String((e && e.message) || "草稿识别失败，请再试一次。");
    } finally {
      label.textContent = "加入纸上草稿";
      input.value = "";
    }
  }
  function backToStart() {
    try {
      window.localStorage.removeItem(STORAGE_KEY);
    } catch (e) {}
    showPage("start");
    document.dispatchEvent(new CustomEvent("blackout:restart"));
  }
  function init() {
    el("copyBtn").addEventListener("click", copyMarkdown);
    el("restartBtn").addEventListener("click", backToStart);
    el("sketchInput").addEventListener("change", function () {
      const input = el("sketchInput");
      if (input.files && input.files[0]) {
        uploadSketch(input.files[0]);
      }
    });
  }
  document.addEventListener("DOMContentLoaded", init);
  return {
    showResult: showResult,
    showPage: showPage,
    backToStart: backToStart,
    setSession: function (id) { sessionId = String(id || ""); }
  };
})();
", "path": "app/static/js/result.js"}, {"content": ""use strict";
window.BlackoutBlack = (function () {
  const STORAGE_KEY = "blackout_active_session_id";
  const ENTRY_TEXT = "黑屏开始。我在听，你直接说就行。按空格暂停，想结束就说结束，或者按 Esc。";
  const RESUMED_TEXT = "接着刚才的继续。";
  let sessionId = "";
  let socket = null;
  let capture = null;
  let recorder = null;
  let mode = "realtime";
  let paused = false;
  let finishing = false;
  let entered = false;
  let readySeen = false;
  let fallbackSeen = false;
  let intentionalClose = false;
  let wasFullscreen = false;
  let wakeLock = null;
  let resumedEntry = false;
  let speechEpoch = 0;
  let speechChain = Promise.resolve();
  let ttsPlaying = false;
  let unmuteTimer = 0;
  let readyTimer = 0;
  let pollTimer = 0;
  let hintTimer = 0;
  let hintRemoveTimer = 0;
  let longPressTimer = 0;
  let suppressTapUntil = 0;
  let pttRecording = false;
  let pttStarting = false;
  let flowGeneration = 0;
  function el(id) {
    return document.getElementById(id);
  }
  function showBlack() {
    el("page-start").hidden = true;
    el("page-result").hidden = true;
    el("page-black").hidden = false;
  }
  function showStart() {
    el("page-black").hidden = true;
    el("page-result").hidden = true;
    el("page-start").hidden = false;
    document.dispatchEvent(new CustomEvent("blackout:restart"));
  }
  function setDot(state) {
    el("dot").className = "dot " + state;
  }
  function sendJson(payload) {
    try {
      if (socket && socket.readyState === WebSocket.OPEN) {
        socket.send(JSON.stringify(payload));
      }
    } catch (e) {}
  }
  function applyMuted() {
    if (capture) {
      capture.setMuted(ttsPlaying || paused);
    }
  }
  function scheduleUnmute() {
    window.clearTimeout(unmuteTimer);
    unmuteTimer = window.setTimeout(function () {
      if (!ttsPlaying) {
        applyMuted();
      }
    }, 300);
  }
  function say(text, kind) {
    const epoch = speechEpoch;
    const spoken = String(text || "");
    if (!spoken) {
      return Promise.resolve();
    }
    speechChain = speechChain.then(async function () {
      if (epoch !== speechEpoch || !entered) {
        return;
      }
      if (kind === "announcement") {
        window.BlackoutCues.chime();
      }
      ttsPlaying = true;
      window.clearTimeout(unmuteTimer);
      applyMuted();
      setDot("speaking");
      if (mode === "realtime") {
        sendJson({ type: "tts_started" });
      }
      try {
        await window.BlackoutSpeech.speak(spoken);
      } finally {
        if (mode === "realtime") {
          sendJson({ type: "tts_finished" });
        }
        ttsPlaying = false;
        if (entered && !finishing) {
          setDot(paused ? "paused" : "listening");
        }
        scheduleUnmute();
      }
    });
    return speechChain;
  }
  function cutOffSpeech() {
    speechEpoch += 1;
    window.BlackoutSpeech.cancel();
  }
  async function requestWakeLock() {
    try {
      if (navigator.wakeLock && navigator.wakeLock.request) {
        wakeLock = await navigator.wakeLock.request("screen");
      }
    } catch (e) {}
  }
  async function releaseWakeLock() {
    try {
      if (wakeLock && wakeLock.release) {
        await wakeLock.release();
      }
    } catch (e) {}
    wakeLock = null;
  }
  async function requestFullscreen() {
    try {
      if (document.documentElement.requestFullscreen && !document.fullscreenElement) {
        await document.documentElement.requestFullscreen();
      }
      if (document.fullscreenElement) {
        wasFullscreen = true;
      }
    } catch (e) {}
  }
  async function leaveFullscreen() {
    try {
      if (document.exitFullscreen && document.fullscreenElement) {
        await document.exitFullscreen();
      }
    } catch (e) {}
  }
  function resetHint() {
    window.clearTimeout(hintTimer);
    window.clearTimeout(hintRemoveTimer);
    let hint = el("hint");
    if (!hint) {
      hint = document.createElement("div");
      hint.id = "hint";
      hint.className = "hint";
      hint.textContent = "空格暂停 · 说“结束”或按 Esc 结束";
      el("page-black").appendChild(hint);
    }
    hint.classList.remove("fading");
    hintTimer = window.setTimeout(function () {
      hint.classList.add("fading");
      hintRemoveTimer = window.setTimeout(function () {
        if (hint.parentNode) {
          hint.parentNode.removeChild(hint);
        }
      }, 1100);
    }, 5000);
  }
  function stopPolling() {
    window.clearInterval(pollTimer);
    pollTimer = 0;
  }
  async function stopCapture() {
    if (capture) {
      const current = capture;
      capture = null;
      await current.stop();
    }
    if (recorder) {
      const currentRecorder = recorder;
      recorder = null;
      pttRecording = false;
      pttStarting = false;
      await currentRecorder.cancel();
    }
  }
  function closeSocket() {
    intentionalClose = true;
    window.clearTimeout(readyTimer);
    if (socket) {
      const current = socket;
      socket = null;
      try {
        current.close();
      } catch (e) {}
    }
  }
  async function returnToStartForPermission() {
    flowGeneration += 1;
    await stopCapture();
    closeSocket();
    stopPolling();
    entered = false;
    await leaveFullscreen();
    await releaseWakeLock();
    showStart();
    window.BlackoutSpeech.speak("需要麦克风权限，请允许后重试。");
  }
  function isPermissionError(error) {
    return Boolean(error && (error.name === "NotAllowedError" || error.name === "SecurityError"));
  }
  async function startRealtimeCapture(gen) {
    capture = window.BlackoutCapture.createStreamCapture(function (frame) {
      try {
        if (socket && socket.readyState === WebSocket.OPEN && mode === "realtime") {
          socket.send(frame);
        }
      } catch (e) {}
    });
    applyMuted();
    try {
      const opened = await capture.start();
      if (!opened || gen !== flowGeneration || !entered) {
        await stopCapture();
        return;
      }
    } catch (e) {
      if (gen !== flowGeneration || !entered) {
        return;
      }
      if (isPermissionError(e)) {
        await returnToStartForPermission();
      } else {
        handleFallback("语音连接不可用，请用按住说话。");
      }
    }
  }
  function pollAnnouncements() {
    stopPolling();
    pollTimer = window.setInterval(async function () {
      if (!entered || mode !== "ptt" || finishing) {
        return;
      }
      try {
        const response = await fetch("/api/sessions/" + sessionId + "/announcements");
        if (!response.ok) {
          return;
        }
        const data = await response.json();
        (data.announcements || []).forEach(function (item) {
          if (item && item.text) {
            say(String(item.text), String(item.kind || "announcement"));
          }
        });
      } catch (e) {}
    }, 5000);
  }
  function handleFallback(message) {
    if (fallbackSeen || finishing || !entered) {
      return;
    }
    fallbackSeen = true;
    mode = "ptt";
    window.clearTimeout(readyTimer);
    if (capture) {
      const current = capture;
      capture = null;
      current.stop();
    }
    closeSocket();
    setDot("listening");
    pollAnnouncements();
    say(String(message || "语音连接不可用，请用按住说话。"), "reply");
  }
  function onSocketMessage(event) {
    let data = null;
    try {
      data = JSON.parse(String(event.data));
    } catch (e) {
      return;
    }
    if (!data || !data.type) {
      return;
    }
    if (data.type === "ready") {
      readySeen = true;
      window.clearTimeout(readyTimer);
      setDot("listening");
      startRealtimeCapture(flowGeneration);
      say(resumedEntry ? RESUMED_TEXT : ENTRY_TEXT, "reply");
    } else if (data.type === "say") {
      say(String(data.text || ""), String(data.kind || "reply"));
    } else if (data.type === "tick") {
      window.BlackoutCues.tick();
    } else if (data.type === "end") {
      endSession(String(data.reason || "phrase"));
    } else if (data.type === "fallback") {
      handleFallback(String(data.message || "语音连接不可用，请用按住说话。"));
    } else if (data.type === "reconnecting") {
      setDot("reconnecting");
    }
  }
  function connectSocket() {
    const scheme = window.location.protocol === "https:" ? "wss:" : "ws:";
    socket = new WebSocket(scheme + "//" + window.location.host + "/ws/sessions/" + sessionId);
    socket.binaryType = "arraybuffer";
    socket.onmessage = onSocketMessage;
    socket.onerror = function () {
      if (!intentionalClose && !fallbackSeen && !finishing) {
        handleFallback("语音连接不可用，请用按住说话。");
      }
    };
    socket.onclose = function () {
      if (!intentionalClose && !fallbackSeen && !finishing && entered) {
        handleFallback("语音连接不可用，请用按住说话。");
      }
    };
    readyTimer = window.setTimeout(function () {
      if (!readySeen && !fallbackSeen && entered) {
        handleFallback("语音连接不可用，请用按住说话。");
      }
    }, 8000);
  }
  async function togglePause() {
    paused = !paused;
    if (paused) {
      sendJson({ type: "pause" });
      window.BlackoutCues.fall();
      setDot("paused");
    } else {
      sendJson({ type: "resume" });
      window.BlackoutCues.rise();
      setDot("listening");
    }
    applyMuted();
  }
  async function startPtt() {
    if (pttRecording || pttStarting || finishing) {
      return;
    }
    pttStarting = true;
    recorder = window.BlackoutCapture.createWavRecorder();
    const gen = flowGeneration;
    try {
      const opened = await recorder.start();
      if (!opened || gen !== flowGeneration || !entered) {
        if (recorder) {
          await recorder.cancel();
          recorder = null;
        }
        pttStarting = false;
        return;
      }
      pttRecording = true;
      pttStarting = false;
      window.BlackoutCues.rise();
      setDot("speaking");
    } catch (e) {
      pttStarting = false;
      recorder = null;
      if (isPermissionError(e)) {
        await returnToStartForPermission();
      }
    }
  }
  async function stopPtt() {
    if (!pttRecording || !recorder) {
      return;
    }
    pttRecording = false;
    const current = recorder;
    recorder = null;
    window.BlackoutCues.fall();
    setDot("listening");
    const wav = await current.stop();
    if (!entered || finishing) {
      return;
    }
    const form = new FormData();
    form.append("audio", wav, "speech.wav");
    try {
      const response = await fetch("/api/sessions/" + sessionId + "/turns", {
        method: "POST",
        body: form
      });
      const data = await response.json();
      if (!response.ok) {
        return;
      }
      if (data.budget_exhausted) {
        endSession("budget");
        return;
      }
      if (data.end) {
        endSession("phrase");
        return;
      }
      if (data.action === "listen" || !data.reply) {
        window.BlackoutCues.tick();
      } else {
        say(String(data.reply), "reply");
      }
    } catch (e) {}
  }
  function toggleAction() {
    if (!entered || finishing) {
      return;
    }
    if (ttsPlaying || window.BlackoutSpeech.speaking()) {
      cutOffSpeech();
      return;
    }
    if (mode === "ptt") {
      if (pttRecording) {
        stopPtt();
      } else {
        startPtt();
      }
      return;
    }
    togglePause();
  }
  async function endSession(reason) {
    if (finishing || !entered) {
      return;
    }
    finishing = true;
    flowGeneration += 1;
    stopPolling();
    window.clearTimeout(readyTimer);
    window.clearTimeout(hintTimer);
    window.clearTimeout(hintRemoveTimer);
    cutOffSpeech();
    await stopCapture();
    closeSocket();
    const line = reason === "budget" ? "预算用完了，我把内容整理出来。" : "好，我来整理";
    const spoken = window.BlackoutSpeech.speak(line);
    spoken.catch(function () {});
    let result = null;
    try {
      const response = await fetch("/api/sessions/" + sessionId + "/finish", { method: "POST" });
      const data = await response.json();
      if (!response.ok) {
        throw new Error("finish failed");
      }
      result = data;
    } catch (e) {
      finishing = false;
      entered = true;
      window.BlackoutSpeech.speak("生成成果失败，按 Esc 再试一次。");
      return;
    }
    try {
      window.localStorage.removeItem(STORAGE_KEY);
    } catch (e) {}
    entered = false;
    await leaveFullscreen();
    await releaseWakeLock();
    window.BlackoutResult.showResult(result, sessionId);
  }
  async function enter(id, resumed) {
    sessionId = String(id);
    resumedEntry = Boolean(resumed);
    mode = "realtime";
    paused = false;
    finishing = false;
    entered = true;
    readySeen = false;
    fallbackSeen = false;
    intentionalClose = false;
    wasFullscreen = false;
    speechEpoch += 1;
    speechChain = Promise.resolve();
    ttsPlaying = false;
    flowGeneration += 1;
    try {
      window.localStorage.setItem(STORAGE_KEY, sessionId);
    } catch (e) {}
    window.BlackoutResult.setSession(sessionId);
    showBlack();
    setDot("reconnecting");
    resetHint();
    requestFullscreen();
    requestWakeLock();
    connectSocket();
  }
  function stopForUnload() {
    flowGeneration += 1;
    stopPolling();
    cutOffSpeech();
    if (capture) {
      capture.stop();
      capture = null;
    }
    if (recorder) {
      recorder.cancel();
      recorder = null;
    }
    closeSocket();
  }
  function init() {
    document.addEventListener("keydown", function (event) {
      if (el("page-black").hidden) {
        return;
      }
      if (event.code === "Space") {
        if (event.repeat) {
          return;
        }
        event.preventDefault();
        toggleAction();
      } else if (event.key === "Escape") {
        event.preventDefault();
        endSession("phrase");
      }
    });
    el("page-black").addEventListener("click", function () {
      if (Date.now() < suppressTapUntil) {
        return;
      }
      toggleAction();
    });
    el("page-black").addEventListener("touchstart", function () {
      window.clearTimeout(longPressTimer);
      longPressTimer = window.setTimeout(function () {
        suppressTapUntil = Date.now() + 700;
        endSession("phrase");
      }, 800);
    }, { passive: true });
    el("page-black").addEventListener("touchend", function () {
      window.clearTimeout(longPressTimer);
    }, { passive: true });
    document.addEventListener("fullscreenchange", function () {
      if (document.fullscreenElement) {
        wasFullscreen = true;
        return;
      }
      if (wasFullscreen && entered && !el("page-black").hidden && !finishing) {
        endSession("phrase");
      }
    });
    document.addEventListener("visibilitychange", function () {
      if (!document.hidden && entered && !el("page-black").hidden) {
        requestWakeLock();
      }
    });
    window.addEventListener("beforeunload", stopForUnload);
    window.addEventListener("pagehide", stopForUnload);
  }
  document.addEventListener("DOMContentLoaded", init);
  return { enter: enter, endSession: endSession };
})();
", "path": "app/static/js/black.js"}, {"content": ""use strict";
window.BlackoutStart = (function () {
  const STORAGE_KEY = "blackout_active_session_id";
  let goalRecorder = null;
  let goalRecording = false;
  let goalStarting = false;
  function el(id) {
    return document.getElementById(id);
  }
  function errorMessage(data) {
    if (data && data.error && data.error.message) {
      return String(data.error.message);
    }
    return "出了一点问题，请再试一次。";
  }
  function primeAudio() {
    window.BlackoutCues.ensure();
    window.BlackoutSpeech.prime();
  }
  function storedId() {
    try {
      return window.localStorage.getItem(STORAGE_KEY) || "";
    } catch (e) {
      return "";
    }
  }
  function clearStored() {
    try {
      window.localStorage.removeItem(STORAGE_KEY);
    } catch (e) {}
  }
  async function fetchJson(url, options) {
    const response = await fetch(url, options || {});
    const data = await response.json();
    if (!response.ok) {
      throw new Error(errorMessage(data));
    }
    return data;
  }
  async function openFinished(id) {
    const record = await fetchJson("/api/sessions/" + id);
    if (record.result) {
      clearStored();
      window.BlackoutResult.showResult(record.result, id);
    }
  }
  function enterActive(id, resumed) {
    try {
      window.localStorage.setItem(STORAGE_KEY, id);
    } catch (e) {}
    window.BlackoutBlack.enter(id, resumed);
  }
  function makeSessionButton(text, handler) {
    const button = document.createElement("button");
    button.type = "button";
    button.textContent = text;
    button.addEventListener("click", handler);
    return button;
  }
  async function refreshList() {
    const box = el("recentList");
    box.replaceChildren();
    el("continueLastBtn").hidden = !storedId();
    try {
      const data = await fetchJson("/api/sessions");
      const sessions = data.sessions || [];
      if (sessions.length === 0) {
        const note = document.createElement("p");
        note.className = "empty-note";
        note.textContent = "还没有记录。";
        box.appendChild(note);
        return;
      }
      sessions.forEach(function (session) {
        const item = document.createElement("div");
        item.className = "session-item";
        const goal = document.createElement("span");
        goal.className = "session-goal";
        goal.textContent = String(session.goal || "");
        item.appendChild(goal);
        if (session.status === "finished") {
          item.appendChild(makeSessionButton("查看成果", function () {
            primeAudio();
            openFinished(String(session.id));
          }));
        } else {
          item.appendChild(makeSessionButton("继续", function () {
            primeAudio();
            enterActive(String(session.id), true);
          }));
        }
        item.appendChild(makeSessionButton("删除", async function () {
          if (!window.confirm("确定删除这次思考吗？")) {
            return;
          }
          await fetch("/api/sessions/" + session.id, { method: "DELETE" });
          if (storedId() === String(session.id)) {
            clearStored();
          }
          refreshList();
        }));
        box.appendChild(item);
      });
    } catch (e) {}
  }
  async function stopGoalRecorder(send) {
    if (!goalRecording || !goalRecorder) {
      return;
    }
    goalRecording = false;
    const recorder = goalRecorder;
    goalRecorder = null;
    el("micBtn").textContent = "语音输入目标";
    if (!send) {
      await recorder.cancel();
      return;
    }
    const wav = await recorder.stop();
    const form = new FormData();
    form.append("audio", wav, "goal.wav");
    try {
      const data = await fetchJson("/api/transcribe", { method: "POST", body: form });
      el("goalInput").value = String(data.transcript || "");
    } catch (e) {
      el("startErr").textContent = String((e && e.message) || "没听清，请再说一次。");
    }
  }
  async function toggleGoalMic() {
    if (goalStarting) {
      return;
    }
    if (goalRecording) {
      await stopGoalRecorder(true);
      return;
    }
    goalStarting = true;
    goalRecorder = window.BlackoutCapture.createWavRecorder();
    try {
      const opened = await goalRecorder.start();
      if (!opened) {
        goalRecorder = null;
        goalStarting = false;
        return;
      }
      goalRecording = true;
      el("micBtn").textContent = "停止录音";
      el("startErr").textContent = "正在录目标，再点一次结束。";
    } catch (e) {
      goalRecorder = null;
      el("startErr").textContent = "需要麦克风权限，请允许后重试。";
    }
    goalStarting = false;
  }
  async function startNew() {
    primeAudio();
    const goal = el("goalInput").value.trim();
    el("startErr").textContent = "";
    if (!goal) {
      el("startErr").textContent = "请先说一下本次目标。";
      return;
    }
    try {
      const data = await fetchJson("/api/sessions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ goal: goal })
      });
      const id = String(data.session_id);
      try {
        window.localStorage.setItem(STORAGE_KEY, id);
      } catch (e) {}
      if (el("openObserver").checked) {
        window.open("/observer?session=" + encodeURIComponent(id), "_blank");
      }
      window.BlackoutBlack.enter(id, false);
    } catch (e) {
      el("startErr").textContent = String((e && e.message) || "网络不太好，请重试。");
    }
  }
  async function continueLast() {
    primeAudio();
    const id = storedId();
    if (!id) {
      return;
    }
    try {
      const record = await fetchJson("/api/sessions/" + id);
      if (record.status === "finished" && record.result) {
        clearStored();
        window.BlackoutResult.showResult(record.result, id);
        return;
      }
    } catch (e) {
      clearStored();
      refreshList();
      return;
    }
    enterActive(id, true);
  }
  function backToStart() {
    el("page-black").hidden = true;
    el("page-result").hidden = true;
    el("page-start").hidden = false;
    refreshList();
  }
  async function init() {
    el("startBtn").addEventListener("click", startNew);
    el("continueLastBtn").addEventListener("click", continueLast);
    el("micBtn").addEventListener("click", toggleGoalMic);
    document.addEventListener("blackout:restart", refreshList);
    window.addEventListener("beforeunload", function () {
      if (goalRecorder) {
        goalRecorder.cancel();
        goalRecorder = null;
        goalRecording = false;
      }
    });
    refreshList();
    const hasChinese = await window.BlackoutSpeech.hasChineseVoice();
    el("voiceWarning").hidden = hasChinese;
  }
  document.addEventListener("DOMContentLoaded", init);
  return { backToStart: backToStart, refreshList: refreshList };
})();
", "path": "app/static/js/start.js"}, {"content": """"Client-side hard spend cap for the Meta Model API."""
import json
import logging
from pathlib import Path
from typing import Any, NamedTuple

import httpx
import openai

logger: logging.Logger = logging.getLogger(__name__)

STOP_AT_USD: float = 140.0
LEDGER_FILE: Path = Path(__file__).parent / ".muse_spend.jsonl"
METERED_PATHS: tuple[str, ...] = ("/v1/responses", "/v1/chat/completions")
TRANSCRIBE_PATH: str = "/v1/asr/transcribe"
TRANSCRIBE_MODEL: str = "muse-voice-transcribe-1.0"
TRANSCRIBE_USD_PER_HOUR: float = 0.18
TRANSCRIBE_WORST_CASE_USD: float = 0.03
WEB_SEARCH_USD_PER_QUERY: float = 2.50 / 1000.0
WEB_SEARCH_WORST_CASE_QUERIES: int = 10


class Price(NamedTuple):
    """USD per 1M tokens."""

    input: float
    cached_input: float
    output: float


PRICES: dict[str, Price] = {
    "muse-wonder-1.0": Price(4.00, 0.20, 20.00),
    "muse-spark-1.3": Price(1.25, 0.15, 4.25),
    "muse-spark-1.2": Price(1.25, 0.15, 4.25),
    "muse-spark-1.1": Price(1.25, 0.15, 4.25),
    "muse-spark-1.3-contributor": Price(0.10, 0.002, 0.20),
    "muse-spark-1.2-contributor": Price(0.10, 0.002, 0.20),
}


def _ledger_path(ledger: Path | None) -> Path:
    """Resolve None to the module's current LEDGER_FILE at call time."""
    return LEDGER_FILE if ledger is None else ledger


def spent_usd(ledger: Path | None = None) -> float:
    """Sum the JSONL ledger; 0.0 if missing."""
    path: Path = _ledger_path(ledger)
    try:
        text: str = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        return 0.0
    total: float = 0.0
    for line in text.splitlines():
        if not line.strip():
            continue
        try:
            row: Any = json.loads(line)
        except Exception as exc:
            raise ValueError(f"spend ledger is unreadable: invalid JSON: {line!r}") from exc
        if not isinstance(row, dict):
            raise ValueError(f"spend ledger is unreadable: not an object: {line!r}")
        usd_val: Any = row.get("usd")
        if isinstance(usd_val, bool) or not isinstance(usd_val, (int, float)):
            raise ValueError(f"spend ledger is unreadable: bad usd value: {line!r}")
        total += float(usd_val)
    return total


def ledger_ok(ledger: Path | None = None) -> bool:
    """Whether the ledger can be read."""
    try:
        spent_usd(ledger)
    except Exception:
        return False
    return True


def can_spend(additional_usd: float = 0.0, ledger: Path | None = None, limit_usd: float | None = None) -> bool:
    """Whether additional spend is allowed; a corrupt ledger cannot spend."""
    path: Path = _ledger_path(ledger)
    limit: float = STOP_AT_USD if limit_usd is None else limit_usd
    try:
        spent: float = spent_usd(path)
    except Exception:
        return False
    additional: float = max(0.0, float(additional_usd))
    if additional == 0.0:
        return spent < float(limit)
    return spent + additional <= float(limit)


def record_spend(ledger: Path, model: str, usd: float) -> None:
    """Append one spend line; append-only for concurrent processes."""
    ledger.parent.mkdir(parents=True, exist_ok=True)
    row: str = json.dumps({"model": model, "usd": usd})
    with open(ledger, "a", encoding="utf-8") as fh:
        fh.write(row + "\n")


def record_audio_seconds(seconds: float, ledger: Path | None = None) -> float:
    """Record realtime-audio spend for `seconds` and return its USD cost."""
    path: Path = _ledger_path(ledger)
    cost: float = max(0.0, float(seconds)) / 3600.0 * TRANSCRIBE_USD_PER_HOUR
    if cost:
        record_spend(path, TRANSCRIBE_MODEL, cost)
    return cost


def max_output_tokens(body: dict[str, Any]) -> int | None:
    """First truthy max-output value or None."""
    for key in ("max_output_tokens", "max_completion_tokens", "max_tokens"):
        val: Any = body.get(key)
        if val:
            try:
                return int(val)
            except Exception:
                return None
    return None


def _web_search_tool_count(body: dict[str, Any]) -> int:
    tools: Any = body.get("tools")
    if not isinstance(tools, list):
        return 0
    count: int = 0
    for tool in tools:
        if isinstance(tool, dict) and tool.get("type") == "web_search":
            count += 1
    return count


def web_search_call_count(data: Any) -> int:
    """Number of billed web_search_call items in a Responses payload."""
    if not isinstance(data, dict):
        return 0
    output: Any = data.get("output")
    if not isinstance(output, list):
        return 0
    count: int = 0
    for item in output:
        if isinstance(item, dict) and item.get("type") == "web_search_call":
            count += 1
    return count


def refusal_reason(path: str, body: dict[str, Any]) -> str | None:
    """Return refusal message or None if the call can be metered."""
    if path not in METERED_PATHS:
        return f"{path} has no price rule in budget.py"
    model: Any = body.get("model")
    if not isinstance(model, str) or model not in PRICES:
        return f"model {model!r} has no price in budget.py"
    if body.get("stream") or body.get("background"):
        return "streaming and background calls cannot be metered"
    tools: Any = body.get("tools")
    if isinstance(tools, list):
        for tool in tools:
            if not isinstance(tool, dict):
                return f"built-in tool {tool!r} has no price in budget.py"
            ttype: Any = tool.get("type", "")
            if ttype == "web_search":
                if path == "/v1/responses":
                    continue
                return "built-in search tools are billed per query and cannot be metered"
            if isinstance(ttype, str) and "search" in ttype.lower():
                return "built-in search tools are billed per query and cannot be metered"
            if ttype != "function":
                return f"built-in tool {ttype!r} has no price in budget.py"
    if not max_output_tokens(body):
        return "set max_output_tokens so the worst-case cost is known"
    return None


def worst_case_usd(body: dict[str, Any], request_bytes: int) -> float:
    """Worst-case cost: input bytes, max output tokens, ten searches if searching."""
    model: Any = body.get("model", "")
    price: Price | None = PRICES.get(model) if isinstance(model, str) else None
    if price is None:
        return 0.0
    max_out: int = max_output_tokens(body) or 0
    in_tokens: float = float(request_bytes) / 2.0
    tokens: float = in_tokens / 1_000_000 * price.input + max_out / 1_000_000 * price.output
    search: float = WEB_SEARCH_WORST_CASE_QUERIES * WEB_SEARCH_USD_PER_QUERY if _web_search_tool_count(body) else 0.0
    return tokens + search


def actual_usd(model: str, usage: dict[str, Any]) -> float:
    """Actual cost from usage; missing counts raise KeyError."""
    price: Price = PRICES[model]
    if "input_tokens" in usage:
        in_total: Any = usage["input_tokens"]
    elif "prompt_tokens" in usage:
        in_total = usage["prompt_tokens"]
    else:
        raise KeyError("input_tokens")
    if "output_tokens" in usage:
        out_total: Any = usage["output_tokens"]
    elif "completion_tokens" in usage:
        out_total = usage["completion_tokens"]
    else:
        raise KeyError("output_tokens")
    if not isinstance(in_total, (int, float)):
        raise KeyError("input_tokens")
    if not isinstance(out_total, (int, float)):
        raise KeyError("output_tokens")
    cached: int = 0
    for key in ("input_tokens_details", "prompt_tokens_details"):
        det: Any = usage.get(key)
        if isinstance(det, dict) and isinstance(det.get("cached_tokens"), (int, float)):
            cached = int(det["cached_tokens"])
            break
    rest: float = float(in_total) - float(cached)
    return rest / 1_000_000 * price.input + float(cached) / 1_000_000 * price.cached_input + float(out_total) / 1_000_000 * price.output


def refusal_response(request: httpx.Request, message: str) -> httpx.Response:
    """Local 402 refusal; never raise from send."""
    body: bytes = json.dumps({"error": {"code": "local_budget_guard", "message": f"Blocked locally: {message}"}}).encode("utf-8")
    return httpx.Response(402, content=body, headers={"Content-Type": "application/json"}, request=request)


def _duration_ms(data: Any) -> float | None:
    """Find audio duration ms in a transcribe response."""
    if isinstance(data, dict):
        for key in ("audioDurationMs", "audio_duration_ms", "durationMs", "duration_ms"):
            val: Any = data.get(key)
            if isinstance(val, (int, float)):
                return float(val)
        usage: Any = data.get("usage")
        if isinstance(usage, dict):
            found: float | None = _duration_ms(usage)
            if found is not None:
                return found
    return None


def _read_body(resp: httpx.Response) -> None:
    """Read response body, ignoring errors."""
    try:
        resp.read()
    except Exception:
        pass


class BudgetedHttpClient(openai.DefaultHttpxClient):
    """httpx client that enforces a hard spend cap locally."""

    def __init__(self, *, ledger: Path | None = None, limit_usd: float | None = None, **kwargs: Any) -> None:
        super().__init__(**kwargs)
        self._ledger: Path = _ledger_path(ledger)
        self._limit_usd: float = STOP_AT_USD if limit_usd is None else limit_usd

    def send(self, request: httpx.Request, **kwargs: Any) -> httpx.Response:
        if request.method.upper() == "GET":
            return super().send(request, **kwargs)
        path: str = request.url.path
        if path == TRANSCRIBE_PATH:
            return self._send_transcribe(request, **kwargs)
        return self._send_metered(request, **kwargs)

    def _send_transcribe(self, request: httpx.Request, **kwargs: Any) -> httpx.Response:
        try:
            spent: float = spent_usd(self._ledger)
        except ValueError:
            return refusal_response(request, "spend ledger is unreadable, request blocked")
        if spent + TRANSCRIBE_WORST_CASE_USD > self._limit_usd:
            return refusal_response(request, "spending limit exceeded for transcription")
        resp: httpx.Response = super().send(request, **kwargs)
        _read_body(resp)
        if not 200 <= resp.status_code < 300:
            return resp
        try:
            ms: float | None = _duration_ms(resp.json())
            if ms is None:
                raise ValueError("no duration")
            cost: float = ms / 3_600_000 * TRANSCRIBE_USD_PER_HOUR
        except Exception:
            cost = TRANSCRIBE_WORST_CASE_USD
        try:
            record_spend(self._ledger, TRANSCRIBE_MODEL, cost)
        except Exception:
            logger.exception("record transcribe spend failed")
        return resp

    def _send_metered(self, request: httpx.Request, **kwargs: Any) -> httpx.Response:
        try:
            request.read()
        except Exception:
            pass
        try:
            raw: bytes = request.content or b""
        except Exception:
            return refusal_response(request, "request body is not JSON and cannot be priced")
        try:
            current_spent: float = spent_usd(self._ledger)
        except ValueError:
            return refusal_response(request, "spend ledger is unreadable, request blocked")
        try:
            body: Any = json.loads(raw.decode("utf-8"))
            if not isinstance(body, dict):
                raise ValueError("not a dict")
        except Exception:
            return refusal_response(request, "request body is not JSON and cannot be priced")
        reason: str | None = refusal_reason(request.url.path, body)
        if reason is not None:
            return refusal_response(request, reason)
        worst: float = worst_case_usd(body, len(raw))
        if current_spent + worst > self._limit_usd:
            return refusal_response(request, "spending limit exceeded for this call")
        resp: httpx.Response = super().send(request, **kwargs)
        _read_body(resp)
        if not 200 <= resp.status_code < 300:
            return resp
        model: str = str(body.get("model", ""))
        try:
            data: Any = resp.json()
            usage: Any = data.get("usage") if isinstance(data, dict) else None
            if not isinstance(usage, dict):
                raise ValueError("missing usage")
            cost: float = actual_usd(model, usage) + web_search_call_count(data) * WEB_SEARCH_USD_PER_QUERY
        except Exception:
            cost = worst
        try:
            record_spend(self._ledger, model, cost)
        except Exception:
            logger.exception("record spend failed")
        return resp


if __name__ == "__main__":
    total: float = spent_usd()
    print(f"Spent ${total:.4f} of the ${STOP_AT_USD:.2f} limit")
", "path": "budget.py"}, {"content": """"Tests for budget.py spend guard."""
import json
from pathlib import Path
from typing import Any

import httpx
import openai
import pytest

import budget
from budget import BudgetedHttpClient, actual_usd, can_spend, record_audio_seconds, refusal_reason, spent_usd, web_search_call_count, worst_case_usd

MODEL: str = "muse-spark-1.3"
BASE: str = "https://api.meta.ai/v1"


def _ok_handler(usage: dict[str, Any], seen: dict[str, int]) -> Any:
    def handle(request: httpx.Request) -> httpx.Response:
        seen["n"] = int(seen.get("n", 0)) + 1
        return httpx.Response(200, json={"id": "resp_1", "usage": usage})
    return handle


def _make_openai(ledger: Path, handler: Any, max_retries: int = 0, limit: float = 140.0) -> openai.OpenAI:
    transport: httpx.MockTransport = httpx.MockTransport(handler)
